Strategy settings; `setup` takes the ones to change, over these defaults. `defaultErrors` and `defaultMessages` are
the `authStrategy` texts (`provideNbTexts`), unless the given options set them:

```ts
export enum NbOAuth2ResponseType {
  CODE = 'code',
  TOKEN = 'token',
}

export enum NbOAuth2GrantType {
  AUTHORIZATION_CODE = 'authorization_code',
  PASSWORD = 'password',
  REFRESH_TOKEN = 'refresh_token',
}

export enum NbOAuth2ClientAuthMethod {
  NONE = 'none',
  BASIC = 'basic',
  REQUEST_BODY = 'request-body',
}

export class NbOAuth2AuthStrategyOptions extends NbAuthStrategyOptions {
  name = '';
  baseEndpoint?: string = '';
  clientId = '';
  clientSecret?: string = '';
  clientAuthMethod?: string = NbOAuth2ClientAuthMethod.NONE;
  redirect?: { success?: string | null; failure?: string | null } = {
    success: '/',
    failure: null,
  };
  defaultErrors?: string[] = ['Something went wrong, please try again.'];
  defaultMessages?: string[] = ['You have been successfully authenticated.'];
  authorize?: {
    endpoint?: string;
    redirectUri?: string;
    responseType?: string;
    requireValidToken?: boolean; // used only with NbOAuth2ResponseType.TOKEN
    scope?: string;
    state?: string;
    pkce?: boolean;
    params?: { [key: string]: string };
  } = {
    endpoint: 'authorize',
    responseType: NbOAuth2ResponseType.CODE,
    requireValidToken: true,
    pkce: true,
  };
  token?: {
    endpoint?: string;
    grantType?: string;
    redirectUri?: string;
    scope?: string; // used only with the password grant
    requireValidToken?: boolean;
    class: NbAuthTokenClass;
  } = {
    endpoint: 'token',
    grantType: NbOAuth2GrantType.AUTHORIZATION_CODE,
    requireValidToken: true,
    class: NbAuthOAuth2Token,
  };
  refresh?: {
    endpoint?: string;
    grantType?: string;
    scope?: string;
    requireValidToken?: boolean;
  } = {
    endpoint: 'token',
    grantType: NbOAuth2GrantType.REFRESH_TOKEN,
    requireValidToken: true,
  };
}
```

With `clientAuthMethod` `basic` the client id and secret go in a Basic authorization header, with `request-body`
in the token requests' body; both need `clientId` and `clientSecret`.

The code flow uses PKCE (RFC 7636): a random verifier per sign-in, its S256 challenge on the redirect to
`authorize`, and the verifier with the code to `token`; `authorize.pkce: false` turns it off. Every redirect sends a
state, random unless `authorize.state` sets one, and the way back is refused unless it brings the same state, so a
sign-in this browser didn't start can't complete. Both are kept in `sessionStorage` while the browser is away.

Strategy settings; `setup` takes the ones to change, over these defaults. `defaultErrors` and `defaultMessages` are
the `authStrategy` texts (`provideNbTexts`), unless the given options set them:

```ts
export class NbPasswordAuthStrategyOptions extends NbAuthStrategyOptions {
 name = '';
 baseEndpoint?: string = '/api/auth/';
 login?: boolean | NbPasswordStrategyModule = {
   alwaysFail: false,
   endpoint: 'login',
   method: 'post',
   requireValidToken: true,
   redirect: {
     success: '/',
     failure: null,
   },
   defaultErrors: ['Login/Email combination is not correct, please try again.'],
   defaultMessages: ['You have been successfully logged in.'],
 };
 register?: boolean | NbPasswordStrategyModule = {
   alwaysFail: false,
   endpoint: 'register',
   method: 'post',
   requireValidToken: true,
   redirect: {
     success: '/',
     failure: null,
   },
   defaultErrors: ['Something went wrong, please try again.'],
   defaultMessages: ['You have been successfully registered.'],
 };
 requestPass?: boolean | NbPasswordStrategyModule = {
   endpoint: 'request-pass',
   method: 'post',
   redirect: {
     success: '/',
     failure: null,
   },
   defaultErrors: ['Something went wrong, please try again.'],
   defaultMessages: ['Reset password instructions have been sent to your email.'],
 };
 resetPass?: boolean | NbPasswordStrategyReset = {
   endpoint: 'reset-pass',
   method: 'put',
   redirect: {
     success: '/',
     failure: null,
   },
   resetPasswordTokenKey: 'reset_password_token',
   defaultErrors: ['Something went wrong, please try again.'],
   defaultMessages: ['Your password has been successfully changed.'],
 };
 logout?: boolean | NbPasswordStrategyReset = {
   alwaysFail: false,
   endpoint: 'logout',
   method: 'delete',
   redirect: {
     success: '/',
     failure: null,
   },
   defaultErrors: ['Something went wrong, please try again.'],
   defaultMessages: ['You have been successfully logged out.'],
 };
 refreshToken?: boolean | NbPasswordStrategyModule = {
   endpoint: 'refresh-token',
   method: 'post',
   requireValidToken: true,
   redirect: {
     success: null,
     failure: null,
   },
   defaultErrors: ['Something went wrong, please try again.'],
   defaultMessages: ['Your token has been successfully refreshed.'],
 };
 token?: NbPasswordStrategyToken = {
   class: NbAuthSimpleToken,
   key: 'data.token',
   getter: (module, res, options) => getDeepFromObject(res.body, options.token.key),
 };
 errors?: NbPasswordStrategyMessage = {
   key: 'data.errors',
   getter: (module, res, options) =>
     nbAuthMessages(getDeepFromObject(res.error, options.errors.key, options[module].defaultErrors)),
 };
 messages?: NbPasswordStrategyMessage = {
   key: 'data.messages',
   getter: (module, res, options) =>
     nbAuthMessages(getDeepFromObject(res.body, options.messages.key, options[module].defaultMessages)),
 };
 validation?: {
   password?: {
     required?: boolean;
     minLength?: number;
     maxLength?: number;
     regexp?: string;
   };
   email?: {
     required?: boolean;
     regexp?: string;
   };
   fullName?: {
     required?: boolean;
     minLength?: number;
     maxLength?: number;
     regexp?: string;
   };
 };
}
```

